    return [
        QualityRuleEvaluationRecord(**record)
        for record in repository.list_quality_rule_evaluations(
            conn,
            dataset_name,
            version,
            body=body,
            query_keys=tuple(request.query_params.keys()),
        )
    ]


# --------------------------------------------------------------------------- #
# Privacy policies
# --------------------------------------------------------------------------- #


@app.post(
    "/datasets/{dataset_name}/versions/{version}/privacy-policies",
